//! Which files a tool wrote, which is what [`FileTags::GENERATED`] says.
//!
//! The engine decides it here and nowhere else, so that no connector has to. Three signals count, and each is chosen to miss a generated file before it takes a written one for generated: a marker in a comment among the first lines of the file, a `linguist-generated` attribute in a `.gitattributes`, and a name or a directory that only tools use. The marker belongs to the content of a file, so the parse reads it and the cached facts carry it; the attribute and the name belong to the tree and are read again each time the graph is built.

use ignore::Match;
use ignore::gitignore::{Gitignore, GitignoreBuilder};

use crate::fact::FileTags;
use crate::path::RepoPath;
use crate::repo::RepoView;

/// How many lines at the top of a file may hold the marker. A license comes first in many files and a marker is on the line of the tool's own message, which is within the first few.
const HEADER_LINES: usize = 10;

/// The bytes of a line the marker is looked for in. A marker stands near the start of its line, and a minified file has no other line to give.
const LINE_BYTES: usize = 300;

/// What a comment says when a tool wrote the file, in lower case. These are the words of the tools and stand for themselves.
const MARKERS: [&str; 3] = ["@generated", "code generated", "do not edit"];

/// What a comment says in prose when a tool wrote the file, in lower case. A comment may say it of something other than its own file, as in "these queries are automatically generated as hooks", so the first group counts only when the words that follow name the tool (`generated by json-schema-to-typescript`) or the comment says it of `this file`, and the second names the tool in itself.
const PROSE: [(&str, bool); 7] = [
    ("auto-generated", true),
    ("autogenerated", true),
    ("auto generated", true),
    ("automatically generated", true),
    ("was generated by", false),
    ("is generated by", false),
    ("were generated by", false),
];

/// The words that turn a marker around: `not auto-generated`, `never generated`. A marker after one is not a marker.
const DENIALS: [&str; 3] = ["not", "never", "isn't"];

/// What starts a comment in the languages the connectors read and in the files that go with them, and what ends the comment when it runs on over several lines. A line of such a comment may start with anything.
const COMMENTS: [(&str, Option<&str>); 12] = [
    ("//", None),
    ("/*", Some("*/")),
    ("*", None),
    ("#", None),
    ("--", None),
    (";", None),
    ("%", None),
    ("<!--", Some("-->")),
    ("\"\"\"", Some("\"\"\"")),
    ("'''", Some("'''")),
    ("(*", Some("*)")),
    ("{-", Some("-}")),
];

/// File names a tool gives its output, by what they end with.
const SUFFIXES: [&str; 8] = [
    ".pb.go",
    ".pb.gw.go",
    "_pb2.py",
    "_pb2_grpc.py",
    "_pb2.pyi",
    ".g.dart",
    ".freezed.dart",
    ".gen.go",
];

/// The directory name that only tools write to.
const DIRECTORY: &str = "__generated__";

/// What a file name holds when the file is the template of generated files and not one of them: its header says that what comes out of it is generated.
const TEMPLATES: [&str; 3] = [".template.", ".tmpl.", ".tpl."];

/// `GENERATED` when a comment among the first lines of `text` says a tool wrote the file, and no tag otherwise. A template is the source of generated files, so its own header says nothing about it.
pub(super) fn marked(path: &RepoPath, text: &str) -> FileTags {
    let name = path.file_name();
    if TEMPLATES.iter().any(|template| name.contains(template)) {
        return FileTags::NONE;
    }
    // The closer of the block comment a line is inside of, which lets a line of its text say it with no mark of its own.
    let mut inside: Option<&str> = None;
    for line in text.lines().take(HEADER_LINES) {
        let comment = inside.is_some() || starts_comment(line).is_some();
        let said = comment && says_generated(line);
        inside = match inside {
            Some(closer) => (!line.contains(closer)).then_some(closer),
            None => opens_block(line),
        };
        if said {
            return FileTags::GENERATED;
        }
    }
    FileTags::NONE
}

/// The comment a line starts, as the entry of [`COMMENTS`].
fn starts_comment(line: &str) -> Option<(&'static str, Option<&'static str>)> {
    let line = line.trim_start();
    COMMENTS
        .iter()
        .find(|(start, _)| line.starts_with(start))
        .copied()
}

/// The closer of the block comment a line opens and does not close, `None` when it opens none.
fn opens_block(line: &str) -> Option<&'static str> {
    let (start, closer) = starts_comment(line)?;
    let closer = closer?;
    let rest = line.trim_start().strip_prefix(start)?;
    (!rest.contains(closer)).then_some(closer)
}

/// Whether the line holds one of the [`MARKERS`] or says it in prose, and does not deny it.
fn says_generated(line: &str) -> bool {
    let bytes = line.as_bytes();
    let bytes = bytes.get(..LINE_BYTES).unwrap_or(bytes);
    let denied = |at: usize| denies(bytes.get(..at).unwrap_or_default());
    let by_word = MARKERS.iter().any(|marker| {
        let Some(at) = find_ignoring_case(bytes, marker.as_bytes()) else {
            return false;
        };
        let after = bytes.get(at + marker.len()..).unwrap_or_default();
        // `@generatedBy` and `@generated_by` name something else, and `do not edit` is no claim to deny.
        let word_goes_on = marker.starts_with('@')
            && after
                .first()
                .is_some_and(|next| next.is_ascii_alphanumeric() || *next == b'_');
        let denied = *marker != "do not edit" && denied(at);
        !word_goes_on && !denied
    });
    by_word
        || PROSE.iter().any(|&(words, needs_source)| {
            let Some(at) = find_ignoring_case(bytes, words.as_bytes()) else {
                return false;
            };
            let after = bytes.get(at + words.len()..).unwrap_or_default();
            let source = !needs_source
                || starts_with_word(after, b"by")
                || find_ignoring_case(bytes, b"this file").is_some();
            source && !denied(at)
        })
}

/// Whether `bytes`, past its blanks, starts with `word` as a whole word, ignoring the case of ASCII letters.
fn starts_with_word(bytes: &[u8], word: &[u8]) -> bool {
    let start = bytes
        .iter()
        .position(|byte| !byte.is_ascii_whitespace())
        .unwrap_or(bytes.len());
    let rest = bytes.get(start..).unwrap_or_default();
    rest.get(..word.len())
        .is_some_and(|head| head.eq_ignore_ascii_case(word))
        && rest
            .get(word.len())
            .is_none_or(|next| !next.is_ascii_alphanumeric())
}

/// Where `needle`, in lower case, first stands in `haystack` when the case of ASCII letters is ignored.
fn find_ignoring_case(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    haystack
        .windows(needle.len())
        .position(|window| window.eq_ignore_ascii_case(needle))
}

/// Whether the word right before a marker is one of the [`DENIALS`].
fn denies(before: &[u8]) -> bool {
    let end = before
        .iter()
        .rposition(|byte| !byte.is_ascii_whitespace())
        .map_or(0, |last| last + 1);
    let words = before.get(..end).unwrap_or_default();
    let start = words
        .iter()
        .rposition(u8::is_ascii_whitespace)
        .map_or(0, |space| space + 1);
    let word = words.get(start..).unwrap_or_default();
    DENIALS
        .iter()
        .any(|denial| word.eq_ignore_ascii_case(denial.as_bytes()))
}

/// What the tree says about which files are generated: the `linguist-generated` rules of its `.gitattributes` files, and the names tools give their output.
#[derive(Debug, Default)]
pub(super) struct Rules {
    /// The matcher of each `.gitattributes` that has a rule for the attribute, with the directory it lies in, the shallowest first. A pattern that sets it is a match, and one that unsets it is a whitelist, so the last rule that matches a path decides it, as in git.
    attributes: Vec<(String, Gitignore)>,
}

impl Rules {
    /// Reads every `.gitattributes` of the view that has a rule for `linguist-generated`.
    pub(super) fn read(repo: &RepoView) -> Self {
        let mut attributes = Vec::new();
        for (_, path) in repo.files() {
            if path.file_name() != ".gitattributes" {
                continue;
            }
            let Some(text) = repo.read_regular_file(path.as_str()) else {
                continue;
            };
            if let Some(matcher) = matcher(&text) {
                attributes.push((path.parent().to_owned(), matcher));
            }
        }
        attributes
            .sort_by(|(left, _), (right, _)| depth(left).cmp(&depth(right)).then(left.cmp(right)));
        Self { attributes }
    }

    /// `GENERATED` when an attribute or the name of the file says a tool wrote it, and no tag otherwise.
    pub(super) fn tags(&self, path: &RepoPath) -> FileTags {
        if self.generated(path) {
            FileTags::GENERATED
        } else {
            FileTags::NONE
        }
    }

    fn generated(&self, path: &RepoPath) -> bool {
        let mut by_attribute = None;
        for (dir, matcher) in &self.attributes {
            let Some(relative) = relative_to(path.as_str(), dir) else {
                continue;
            };
            match matcher.matched(relative, false) {
                Match::Ignore(_) => by_attribute = Some(true),
                Match::Whitelist(_) => by_attribute = Some(false),
                Match::None => {}
            }
        }
        // A rule that says the file is not generated settles it against the name too, as it does in linguist.
        by_attribute.unwrap_or_else(|| named(path))
    }
}

/// The path below `dir`, `None` for a path that is not below it.
fn relative_to<'a>(path: &'a str, dir: &str) -> Option<&'a str> {
    if dir.is_empty() {
        return Some(path);
    }
    path.strip_prefix(dir)?.strip_prefix('/')
}

/// How many directories deep `dir` is, `""` being the root.
fn depth(dir: &str) -> usize {
    if dir.is_empty() {
        0
    } else {
        dir.split('/').count()
    }
}

/// The matcher of the `linguist-generated` rules of one `.gitattributes`, `None` when it has none.
fn matcher(text: &str) -> Option<Gitignore> {
    let mut builder = GitignoreBuilder::new("/");
    let mut any = false;
    for line in text.lines() {
        let line = line.trim();
        if line.starts_with('#') {
            continue;
        }
        let mut words = line.split_whitespace();
        let Some(pattern) = words.next() else {
            continue;
        };
        // Within a line the last word about the attribute wins, as it does in git.
        let Some(set) = words.filter_map(attribute_state).next_back() else {
            continue;
        };
        let rule = if set {
            pattern.to_owned()
        } else {
            format!("!{pattern}")
        };
        if builder.add_line(None, &rule).is_ok() {
            any = true;
        }
    }
    if !any {
        return None;
    }
    builder.build().ok()
}

/// What a word of a `.gitattributes` line says about `linguist-generated`: `Some(true)` when it sets it, `Some(false)` when it unsets it or gives it another value, and `None` when it is about another attribute.
fn attribute_state(word: &str) -> Option<bool> {
    const NAME: &str = "linguist-generated";
    if word == NAME {
        return Some(true);
    }
    if let Some(value) = word
        .strip_prefix(NAME)
        .and_then(|rest| rest.strip_prefix('='))
    {
        return Some(value == "true");
    }
    (word.strip_prefix(['-', '!']) == Some(NAME)).then_some(false)
}

/// Whether the name of `path` is one a tool gives its output.
pub(super) fn named(path: &RepoPath) -> bool {
    let name = path.file_name();
    path.parent().split('/').any(|dir| dir == DIRECTORY)
        || name.contains(".generated.")
        || SUFFIXES.iter().any(|suffix| name.ends_with(suffix))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn path(text: &str) -> RepoPath {
        RepoPath::normalize(text).unwrap()
    }

    fn tagged(rules: &Rules, text: &str) -> bool {
        rules.tags(&path(text)).contains(FileTags::GENERATED)
    }

    fn rules(files: &[(&str, &str)]) -> Rules {
        let dir = tempfile::tempdir().unwrap();
        let mut paths = Vec::new();
        for (name, text) in files {
            let absolute = dir.path().join(name);
            std::fs::create_dir_all(absolute.parent().unwrap()).unwrap();
            std::fs::write(&absolute, text).unwrap();
            paths.push(path(name));
        }
        let root = camino::Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
        Rules::read(&RepoView::new(root, paths))
    }

    #[gsttt_scenario::scenario("indexing", "A header marker tags a file")]
    #[test]
    fn a_marker_in_a_comment_among_the_first_lines_tags_the_file() {
        for header in [
            "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x\n",
            "/* eslint-disable */\n// @generated\nexport {};\n",
            "# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\n",
            "/**\n * This class is auto generated by OpenAPI Generator.\n */\n",
            "// This file is automatically generated by tool X.\n",
            "<!-- auto-generated by tool X -->\n<p></p>\n",
            "# ---------\n# THIS FILE WAS AUTOMATICALLY GENERATED (DO NOT MODIFY)\n# ---------\n",
            // A line inside a block comment needs no mark of its own.
            "/*\n  This code was generated by Amplication.\n  Changes to this file will be lost.\n*/\nexport {};\n",
            "\"\"\"\nThis module was generated by tool X.\n\"\"\"\nimport os\n",
        ] {
            assert_eq!(
                marked(&path("a.ts"), header),
                FileTags::GENERATED,
                "{header:?}"
            );
        }
    }

    #[gsttt_scenario::scenario(
        "indexing",
        "A comment that denies or only mentions it tags nothing"
    )]
    #[test]
    fn a_marker_in_code_or_below_the_header_tags_nothing() {
        let late = format!("{}// @generated\n", "let x = 1;\n".repeat(HEADER_LINES));
        let after_block = "/* a license */\nconst note = 'this code was generated by a tool';\n";
        for text in [
            "const note = 'do not edit this';\n",
            "let generated = 1;\n",
            late.as_str(),
            after_block,
            "// the @generatedBy field\n",
            "// This file is not auto-generated.\n",
            "// never automatically generated\n",
            "// these queries are automatically generated as hooks by codegen\n// the file name that ends with .query.ts is automatically generated as a hook\n",
            "// the id was not generated by the server\n",
            "",
        ] {
            assert_eq!(marked(&path("a.ts"), text), FileTags::NONE, "{text:?}");
        }
    }

    #[test]
    fn a_template_is_not_the_file_its_header_says_is_generated() {
        let header = "/***\n * This file was auto-generated by Amplication and should not be modified by hand.\n */\n";
        assert_eq!(
            marked(&path("src/seed.template.ts"), header),
            FileTags::NONE
        );
        assert_eq!(marked(&path("src/seed.ts"), header), FileTags::GENERATED);
    }

    #[test]
    fn a_line_of_any_length_and_any_bytes_is_read() {
        let long = format!("// {}\n", "é".repeat(400));
        assert_eq!(marked(&path("a.ts"), &long), FileTags::NONE);
        let far = format!("// {} @generated\n", "x".repeat(LINE_BYTES));
        assert_eq!(marked(&path("a.ts"), &far), FileTags::NONE);
    }

    #[gsttt_scenario::scenario("indexing", "A name or directory only tools use tags a file")]
    #[test]
    fn names_and_directories_only_tools_use_tag_the_file() {
        let rules = Rules::default();
        for name in [
            "src/__generated__/types.ts",
            "src/api.generated.ts",
            "pkg/x.pb.go",
            "pkg/x.pb.gw.go",
            "svc/x_pb2.py",
            "svc/x_pb2_grpc.py",
            "lib/x.g.dart",
            "lib/x.freezed.dart",
            "pkg/x.gen.go",
        ] {
            assert!(tagged(&rules, name), "{name}");
        }
        for name in [
            "src/generated.ts",
            "src/generator/index.ts",
            "src/generated/helper.ts",
            "src/a_pb2.ts",
            "pkg/pb.go",
        ] {
            assert!(!tagged(&rules, name), "{name}");
        }
    }

    #[gsttt_scenario::scenario("indexing", "A gitattributes rule tags the files it names")]
    #[test]
    fn a_gitattributes_rule_tags_the_files_it_names() {
        let rules = rules(&[
            (
                ".gitattributes",
                "# a comment\n*.min.js linguist-generated\ndocs/api/** linguist-generated=true\n*.md text\n",
            ),
            ("docs/.gitattributes", "keep.md -linguist-generated\n"),
            ("docs/api/a.md", ""),
        ]);
        assert!(tagged(&rules, "dist/a.min.js"));
        assert!(tagged(&rules, "docs/api/a.md"));
        assert!(!tagged(&rules, "docs/api/keep.md"));
        assert!(!tagged(&rules, "docs/a.md"));
        assert!(!tagged(&rules, "src/a.js"));
    }

    #[test]
    fn the_last_rule_that_matches_decides_and_a_deeper_file_overrides() {
        let rules = rules(&[
            (
                ".gitattributes",
                "*.ts linguist-generated\nkeep.ts -linguist-generated\n",
            ),
            (
                "lib/.gitattributes",
                "*.ts linguist-generated=false\nmade.ts linguist-generated\n",
            ),
        ]);
        assert!(tagged(&rules, "a.ts"));
        assert!(!tagged(&rules, "keep.ts"));
        assert!(!tagged(&rules, "lib/a.ts"));
        assert!(tagged(&rules, "lib/made.ts"));
    }

    #[test]
    fn a_rule_that_unsets_the_attribute_settles_it_against_the_name() {
        let rules = rules(&[(
            ".gitattributes",
            "src/__generated__/keep.ts -linguist-generated\n",
        )]);
        assert!(!tagged(&rules, "src/__generated__/keep.ts"));
        assert!(tagged(&rules, "src/__generated__/other.ts"));
    }

    #[test]
    fn a_gitattributes_without_the_attribute_costs_nothing() {
        let rules = rules(&[(".gitattributes", "*.png binary\n*.sh text eol=lf\n")]);
        assert!(rules.attributes.is_empty());
    }
}
